function ways(n, memo = new Map()) {
  if (n < 0) return 0;
  if (n === 0) return 1;
  if (memo.has(n)) return memo.get(n);
  const value = ways(n - 1, memo) + ways(n - 2, memo) + ways(n - 3, memo);
  memo.set(n, value);
  return value;
}

