  { kg: 1, naira: 60000 },
  { kg: 3, naira: 90000 },
  { kg: 4, naira: 100000 },
];

function bestFee(items, capacity) {
  const best = new Array(capacity + 1).fill(0);
  for (const { kg, naira } of items) {
    for (let c = capacity; c >= kg; c--) {
      best[c] = Math.max(best[c], naira + best[c - kg]);
    }
  }
  return best[capacity];
}

