function canSplitEvenly(weights) {
  const total = weights.reduce((s, w) => s + w, 0);
  if (total % 2 !== 0) return false;
  const half = total / 2;
  const possible = new Array(half + 1).fill(false);
  possible[0] = true;
  for (const w of weights) {
    for (let s = half; s >= w; s--) {
      if (possible[s - w]) possible[s] = true;
    }
  }
  return possible[half];
}

console.log(canSplitEvenly([30, 10, 25, 15]), canSplitEvenly([30, 10, 25]), canSplitEvenly([100, 5, 5]));

